body.script:
const xhttp = new XMLHttpRequest();
xhttp.onload = function() {
  const cds = this.responseXML.getElementsByTagName("CD");
  let html = "
TítuloArtistaPaísCompañíaPrecioAño";
  for(let i = 0; i < cds.length; i++) {
    const g = tag => cds[i].getElementsByTagName(tag)[0].childNodes[0].nodeValue;
    html += `
${g("TITLE")}${g("ARTIST")}${g("COUNTRY")}${g("COMPANY")}${g("PRICE")}€${g("YEAR")}`;
  }
  html += "";
  document.getElementById("demo").innerHTML = html;
};
xhttp.open("GET", "https://www.w3schools.com/js/cd_catalog.xml");
xhttp.send();
